def _safe_target(self, rows, current_q, q_limit, preference):
    voltage_range = self.voltage_upper - self.voltage_lower
    lower_margin = min(0.009, 0.2 * voltage_range)
    upper_margin = min(0.008, 0.2 * voltage_range)
    soft_lower = self.voltage_lower + lower_margin
    soft_upper = self.voltage_upper - upper_margin
    lower_q = -q_limit
    upper_q = q_limit
    constrained = False
    sensitivities = {
        bus: self._sensitivity(bus, row[0]) for bus, row in rows.items()
    }

    for bus, (voltage, _, _, _) in rows.items():
        sensitivity = sensitivities[bus]
        if sensitivity <= 0.0:
            continue
        constrained = True
        lower_q = max(
            lower_q, current_q + (soft_lower - voltage) / sensitivity
        )
        upper_q = min(
            upper_q, current_q + (soft_upper - voltage) / sensitivity
        )

    if not constrained or lower_q <= upper_q:
        return _clip(preference, lower_q, upper_q)

def _loss_coefficients():
    """Return Q-load to optimal inverter-Q coefficients under LinDistFlow."""
    parent = [None] * _BUS_COUNT
    edge_r = [0.0] * _BUS_COUNT
    edge_x = [0.0] * _BUS_COUNT
    for branch, reactance in zip(_BRANCHES, _BRANCH_X):
        upstream, downstream, resistance = branch
        parent[downstream] = upstream
        edge_r[downstream] = resistance
        edge_x[downstream] = reactance

    paths = []
    phasor_paths = []
    for bus in range(_BUS_COUNT):
        path = {}
        phasor_path = []
        node = bus
        while node:
            path[node] = edge_r[node]
            phasor_path.append(
                (parent[node], node, edge_r[node], edge_x[node])
            )
            node = parent[node]
        paths.append(path)
        phasor_paths.append(tuple(reversed(phasor_path)))

    def common_resistance(first, second):
        return math.fsum(resistance for edge, resistance in paths[first].items()
                         if edge in paths[second])

    coupling = [[common_resistance(first, second) for second in _PV_BUSES]
                for first in _PV_BUSES]
    inverse = _inverse(coupling)
    load_coupling = [[common_resistance(pv, bus) for bus in range(_BUS_COUNT)]
                     for pv in _PV_BUSES]
    coefficients = []
    for row in inverse:
        values = []
        for bus in range(_BUS_COUNT):
            value = math.fsum(
                weight * load_row[bus]
                for weight, load_row in zip(row, load_coupling)
            )
            values.append(0.0 if abs(value) < 1e-10 else value)
        coefficients.append(tuple(values))
    return tuple(coefficients), tuple(paths), tuple(phasor_paths)

def _reactive_target(self, bus_ids, demands):
    actual = {}
    pairs = zip(bus_ids, demands)
    for _ in range(_BUS_COUNT):
        try:
            external_bus, demand = next(pairs)
        except StopIteration:
            break
        except Exception:
            # A lazy transform may fail while zip advances either source.
            # Stop rather than continuing with potentially misaligned pairs.
            break
        try:
            numeric_bus = _as_float(external_bus)
            value = _as_float(demand)
        except Exception:
            continue
        bus = numeric_bus
        if (numeric_bus.is_integer() and 0 <= bus < _BUS_COUNT and
                math.isfinite(value)):
            bus = int(bus)
            # Regional telemetry may expose more than one load element at a
            # bus.  Their demands are additive, not last-record-wins.
            actual[bus] = actual.get(bus, 0.0) + value

    if not actual:
        # Missing regional load telemetry is not evidence of zero demand.
        # Let act() hold the economic command while retaining voltage control.
        raise ValueError("no usable regional demand telemetry")

    if self.fixed_model:
        nominal_observed = math.fsum(_NOMINAL_Q[bus] for bus in actual)
        actual_observed = math.fsum(actual.values())
        if nominal_observed <= 1e-12:
            raise ValueError("no load-bearing bus in regional telemetry")
        level = _clip(actual_observed / nominal_observed, 0.0, 5.0)
        row = _LOSS_COEFFICIENTS[self.pv_index]
        target = math.fsum(
            row[bus] * actual.get(bus, _NOMINAL_Q[bus] * level)
            for bus in range(_BUS_COUNT)
        )
        # LinDistFlow omits line-consumed vars.  A small common, level-linear
        # uplift is robust to the unobserved peer-PV active-power pattern;
        # the voltage barriers remove it whenever that pattern makes it unsafe.
        if target > 0.0:
            target *= 1.0 + 0.02 * (level if level < 2.0 else 2.0)
        return target

# Project every move against the bound in its direction: even support
# requested near one limit must not jump through the opposite limit.
# Work in physical MVAr so inverter size and solar capability cannot
# weaken protection.  Normally use at most 35% of measured headroom
# before the sensitivity margin, leaving the rest for unseen peer moves,
# and retain 0.001 pu for AC-model error.
if self.fixed_model:
    sensitivity = 1.25 * _MAX_DV_DQ[self.pv_index]
    # Use the measured physical baseline directly, avoiding a needless
    # Q→normalized→Q round trip at capability and action boundaries.
    physical_change = action * capability - reactive
    if physical_change > 0.0:
        voltage_budget = self.upper_voltage - 0.001 - maximum
        if voltage_budget <= 0.0:
            q_budget = 0.0
        else:
            q_budget = (
                _HEADROOM_SHARE * voltage_budget / sensitivity
            )
        if physical_change > q_budget:
            action = (reactive + q_budget) / capability
    elif physical_change < 0.0:
        voltage_budget = minimum - self.lower_voltage - 0.001
        if voltage_budget <= 0.0:
            q_budget = 0.0
        else:
            q_budget = (
                _HEADROOM_SHARE * voltage_budget / sensitivity
            )
        if -physical_change > q_budget:
            action = (reactive - q_budget) / capability
